window.docContents[77].resolve({"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Solver-creation-and-basic-term-creation":{"contents":"def setup : Env (Solver × Term Bool × Term Int) := do\n  let solver ← Solver.new\n  solver.setOption \"produce-models\" \"true\"\n  let b1 ← Term.mkSymbol \"b1\"\n  let i1 ← Term.mkSymbol \"i1\"\n  -- term creation with `smt!` syntax extension\n  let formula ← smt! ¬ b1 ∨ (b1 ∧ 0 < i1)\n  -- same as `formula` without the syntax extension\n  let formula_by_hand ← do\n    let zero ← Term.mkInt 0\n    let i1_pos ← zero.lt i1\n    let conj ← b1.and i1_pos\n    (← b1.not).or conj\n  -- terms are perfectly shared, both formulas are the same\n  if formula != formula_by_hand then\n    panic! \"not perfectly shared 🙀\"\n  solver.assert formula\n  return (solver, b1, i1)\n\n\n","context":"Cvc.lean -- High-Level CVC5 API\u0009Overview","header":"1.1. Solver creation and basic term creation","id":"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Solver-creation-and-basic-term-creation"}});